// Static game data, generated by `npm run data` into public/data/.

export type DropKind = "mission" | "bounty" | "enemy" | "special";
export type Drop = [place: string, chance: number, kind: DropKind];
/** [item, intact, exceptional, flawless, radiant] — percent chances */
export type RelicReward = [item: string, intact: number, exceptional: number, flawless: number, radiant: number];

export interface DropsData {
  updated: number;
  items: Record<string, { drops: Drop[]; relics?: string[] }>;
  relics: Record<string, { vaulted: boolean; rewards: RelicReward[]; drops: Drop[] }>;
  sets: Record<string, { parts: string[]; farmable: number }>;
}

export type Category =
  | "warframe" | "primary" | "secondary" | "melee" | "necramech"
  | "archwing" | "archgun" | "archmelee" | "sentinel" | "pet" | "companionweapon";

export type Polarity = "madurai" | "vazarin" | "naramon" | "zenurik" | "unairu" | "penjaga" | "umbra" | "universal" | "any" | "";

export interface CollectionItem {
  id: string;
  name: string;
  cat: Category;
  type: string;
  mr: number;
  rank: number;
  img: string | null;
  prime: boolean;
  vaulted: boolean;
  released: string | null;
  pol?: Polarity[];
  aura?: Polarity;
  stance?: Polarity;
  abilities?: { name: string; desc: string; img: string }[];
  health?: number; shield?: number; armor?: number; energy?: number;
  wiki?: string;
}

export interface Mod {
  id: string;
  name: string;
  type: string;
  compat: string;
  pol: Polarity;
  rarity: string;
  drain: number;
  ranks: number;
  exilus: boolean;
  augment: boolean;
  img: string | null;
  stats: string;
}

export interface Arcane { name: string; type: string; rarity: string; ranks: number; img: string | null; stats: string }
export interface ShardColor { color: string; stats: { id: string; text: string; tau: string }[] }

export interface GameData {
  drops: DropsData;
  collection: CollectionItem[];
  byId: Map<string, CollectionItem>;
  mods: Mod[];
  modsById: Map<string, Mod>;
  arcanes: Arcane[];
  shards: ShardColor[];
}

let cache: Promise<GameData> | null = null;

async function getJson<T>(file: string): Promise<T> {
  const res = await fetch(`${import.meta.env.BASE_URL}data/${file}`);
  if (!res.ok) throw new Error(`Couldn't load ${file} (${res.status}). Run "npm run data" to generate it.`);
  return res.json() as Promise<T>;
}

export function loadGameData(): Promise<GameData> {
  cache ??= Promise.all([
    getJson<DropsData>("drops.json"),
    getJson<CollectionItem[]>("collection.json"),
    getJson<Mod[]>("mods.json"),
    getJson<Arcane[]>("arcanes.json"),
    getJson<ShardColor[]>("shards.json"),
  ]).then(([drops, collection, mods, arcanes, shards]) => ({
    drops, collection, mods, arcanes, shards,
    byId: new Map(collection.map(c => [c.id, c])),
    modsById: new Map(mods.map(m => [m.id, m])),
  }));
  return cache;
}

export const imageUrl = (img: string | null) => (img ? `https://cdn.warframestat.us/img/${img}` : null);

export const CATEGORY_LABEL: Record<Category, string> = {
  warframe: "Warframes", primary: "Primary", secondary: "Secondary", melee: "Melee",
  sentinel: "Sentinels", pet: "Pets", companionweapon: "Companion weapons",
  archwing: "Archwings", archgun: "Arch-guns", archmelee: "Arch-melee", necramech: "Necramechs",
};

/** Mastery points for taking an item to max rank: 200/rank for frames, companions and vehicles; 100/rank for weapons. */
export function masteryPoints(item: CollectionItem): number {
  const perRank = ["warframe", "sentinel", "pet", "archwing", "necramech"].includes(item.cat) ? 200 : 100;
  return perRank * item.rank;
}
